package com.bank.spark.model;

// A transaction row; duplicates share txnId but may differ in receivedTs.
public class TxnRow {
    private final String txnId;
    private final String channel;
    private final long receivedTs;

    public TxnRow(String txnId, String channel, long receivedTs) {
        this.txnId = txnId;
        this.channel = channel;
        this.receivedTs = receivedTs;
    }

    public String getTxnId() { return txnId; }
    public String getChannel() { return channel; }
    public long getReceivedTs() { return receivedTs; }

    // Full-row equality for distinct().
    @Override public boolean equals(Object o) {
        if (!(o instanceof TxnRow t)) return false;
        return receivedTs == t.receivedTs && txnId.equals(t.txnId) && channel.equals(t.channel);
    }
    @Override public int hashCode() { return java.util.Objects.hash(txnId, channel, receivedTs); }
    @Override public String toString() { return txnId + "/" + channel + "@" + receivedTs; }
}
