package com.bank.spark.service;

import com.bank.spark.model.TxnRow;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

// Models distinct(), dropDuplicates(subset), and latest-wins window dedup.
public class Deduplicator {

    // distinct(): keep only rows unique across ALL columns.
    public List<TxnRow> distinct(List<TxnRow> rows) {
        return new ArrayList<>(new LinkedHashSet<>(rows));
    }

    // dropDuplicates("txnId"): keep first occurrence per txnId (arbitrary survivor).
    public List<TxnRow> dropDuplicatesByTxnId(List<TxnRow> rows) {
        Map<String, TxnRow> byId = new LinkedHashMap<>();
        for (TxnRow r : rows) byId.putIfAbsent(r.getTxnId(), r); // first wins
        return new ArrayList<>(byId.values());
    }

    // Window latest-wins: partition by txnId, order by receivedTs desc, row_number=1.
    public List<TxnRow> latestPerTxnId(List<TxnRow> rows) {
        Map<String, TxnRow> latest = new LinkedHashMap<>();
        for (TxnRow r : rows) {
            TxnRow cur = latest.get(r.getTxnId());
            if (cur == null || r.getReceivedTs() > cur.getReceivedTs()) {
                latest.put(r.getTxnId(), r);
            }
        }
        return new ArrayList<>(latest.values());
    }
}
