package com.bank.spark;

import com.bank.spark.model.TxnRow;
import com.bank.spark.service.Deduplicator;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: distinct vs dropDuplicates(subset) vs latest-wins.
public class DedupDemo {

    private static final Logger log = Logger.getLogger(DedupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Deduplicator dedup = new Deduplicator();

        // T1 sent twice with different receivedTs; T2 once; an exact dup of T2.
        List<TxnRow> rows = List.of(
            new TxnRow("T1", "UPI", 100),
            new TxnRow("T1", "UPI", 250),   // same txn, later copy
            new TxnRow("T2", "NEFT", 300),
            new TxnRow("T2", "NEFT", 300));  // exact whole-row duplicate

        var d = dedup.distinct(rows);
        log.info(() -> "distinct() kept " + d.size() + " rows: " + d
                + " (T1 copies differ → both kept)");

        var s = dedup.dropDuplicatesByTxnId(rows);
        log.info(() -> "dropDuplicates(txnId) kept " + s.size() + " rows: " + s
                + " (one per txnId, first seen)");

        var l = dedup.latestPerTxnId(rows);
        log.info(() -> "latest-wins window kept " + l.size() + " rows: " + l
                + " (T1@250 chosen deterministically)");

        log.info("Dedup demo complete.");
    }
}
